package dev.starfold;

import net.fabricmc.fabric.api.client.rendering.v1.DimensionRenderingRegistry;
import net.minecraft.client.renderer.DimensionSpecialEffects;

/** Keep the accepted overworld-like ground sky; suppress its celestial dome in the new
 * orbital stage. Fog clear colour fades separately to black, without fogging terrain. */
public final class GroundSky extends DimensionSpecialEffects.OverworldEffects {
    public static double darkness(){return GroundClient.ready()?GroundOrbit.weight(GroundClient.eye().y()):0;}
    @Override public SkyType skyType(){return GroundClient.solar()||GroundClient.ready()&&GroundClient.eye().y()>GroundOrbit.START?SkyType.NONE:super.skyType();}
    public static void initialize(){DimensionRenderingRegistry.registerDimensionEffects(GroundServer.DIMENSION.location(),new GroundSky());}
    private GroundSky(){}
}

