package dev.starfold;

import org.joml.Quaterniond;

/** Live mouse aim belongs to the camera, not the last acknowledged movement input.
 * Above local upright navigation it is stored in universe axes, even inside the
 * planet's assistance zone. Chart/planet handoffs must never replay old mouse aim. */
public final class GroundCameraAim {
    // Camera freedom follows the orbital display, not the 1536 movement-policy handoff.
    public static final double LOOK_START=GroundOrbit.START;
    public static boolean universe(GroundTransit.State s){return s.space()||s.local().pose().point().y()>LOOK_START;}
    public static Quaterniond chart(GroundEphemeris.Model model,int planet,GroundMotion.State view,Quaterniond aim,double time){
        return GroundOrbit.frame(view.pose()).rotation().conjugate().mul(model.at(planet,time).rotation().conjugate()).mul(aim).normalize();
    }
    public static Quaterniond reconcile(GroundEphemeris.Model model,GroundTransit.State before,GroundTransit.State after,Quaterniond live){
        // Neither a movement tick nor its acknowledgement owns frame-rate mouse aim.
        // Returning below the orbital display is the boundary for native upright control.
        // Keep the live universe ray through space/local, reference-star and cube-face changes.
        return universe(before)&&universe(after)?new Quaterniond(live):GroundTransit.orientation(model,after,after.tick());
    }
    private GroundCameraAim(){}
}

package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import dev.starfold.CubeSurfaceTopology.Cell;
import org.joml.Quaterniond;
import org.joml.Vector3d;

/** Single-planet flight adapter. Low movement remains the original GroundMotion sweep.
 * Above its old ceiling, position is a reversible six-face address of one spatial shell.
 * The horizon follows local radial up; this is not inertial spacecraft/six-axis flight. */
public final class GroundFlight {
    public static final double HANDOFF=128;
    public static GroundMotion.State step(GroundWorld world,GroundMotion.State old,PlanetMotion.Input input,boolean toggle){
        return step(world,old,input,toggle,false);
    }
    /** Ground's orbital display can keep quaternion look without changing the legacy
     * adapter's default upright navigation or its gravity-relative movement rules. */
    public static GroundMotion.State step(GroundWorld world,GroundMotion.State old,PlanetMotion.Input input,boolean toggle,boolean freeLook){
        if(old.pose().point().y()<=HANDOFF)return GroundMotion.step(world,old,input,toggle);
        boolean flying=toggle?!old.flying():old.flying(),jump=input.rise()>0;
        double vy=flying?0:old.grounded()&&jump&&!old.jumpHeld()?.42:Math.max(-3,(toggle?0:old.vertical())-.08);
        var q=freeLook?input.orientation():GroundView.upright(input.orientation());var f=PlanetMotion.direction(q,0,0,1);var l=PlanetMotion.direction(q,1,0,0);var up=new Point(0,1,0);
        var tangent=new Point(f.x(),0,f.z());if(tangent.length()<1e-5)tangent=l.cross(up);tangent=PlanetSpace.unit(tangent);
        var horizontal=tangent.scale(input.forward()).add(up.cross(tangent).scale(input.left()));if(horizontal.length()>1)horizontal=PlanetSpace.unit(horizontal);
        Point d;
        if(flying){d=(input.direct()?f.scale(input.forward()).add(l.scale(input.left())):horizontal).add(up.scale(input.rise()));double t=GroundGap.smooth(HANDOFF,GroundOrbit.END,old.pose().point().y());double speed=(input.fast()?1.2:.35)*(1-t)+UniverseMotion.speed(old.pose().point().y(),input.fast())*t;d=d.scale(speed/Math.max(1,d.length()));}
        else d=horizontal.scale(input.fast()?.30:.215).add(up.scale(vy));
        var frame=GroundOrbit.frame(old.pose());var origin=GroundOrbit.position(old.pose());var delta=frame.world(d);var current=old.pose();var p=origin;
        // Bounded substeps through actual masked columns. Never skip a tall wall on descent.
        // Above every physical column there is no collision work, but still sample descent.
        int steps=Math.max(1,(int)Math.ceil(delta.length()/.2));var part=delta.scale(1.0/steps);
        for(int i=0;i<steps;i++){
            var next=p.add(part);double radius=next.length();if(radius<GroundOrbit.RADIUS+GroundSpace.MIN+1)break;
            if(radius>GroundOrbit.RADIUS+GroundOrbit.LIMIT)next=next.scale((GroundOrbit.RADIUS+GroundOrbit.LIMIT-1e-7)/radius);
            var pose=GroundOrbit.locate(next);if(!clear(world,pose))break;p=next;current=pose;
        }
        var nextFrame=GroundOrbit.frame(current);
        // A chart change is not a camera turn. Only the legacy upright path
        // transports gravity-up; free look retains the same universe-axis aim.
        var turn=freeLook?new Quaterniond():new Quaterniond().rotationTo(vec(frame.up()),vec(nextFrame.up()));
        q=nextFrame.rotation().conjugate().mul(turn).mul(frame.rotation()).mul(q).normalize();
        boolean grounded=!flying&&!clear(world,new GroundSpace.Pose(current.face(),current.point().sub(new Point(0,.06,0))));
        if(!flying&&(grounded&&vy<0||vy>0&&p.sub(origin).dot(frame.up())<vy*.25))vy=0;
        return new GroundMotion.State(current,vy,grounded,flying,jump,false,freeLook&&current.point().y()>GroundCameraAim.LOOK_START?q:GroundView.upright(q));
    }
    public static boolean clear(GroundWorld w,GroundSpace.Pose pose){
        if(pose.point().y()<=HANDOFF)return GroundMotion.clear(w,pose);
        var p=pose.point();if(p.y()-.901>=Math.max(GroundSpace.MAX,w.config().height()))return true;
        for(int x=(int)Math.floor(p.x()-.3);x<=Math.floor(p.x()+.3);x++)for(int y=(int)Math.floor(p.y()-.9);y<=Math.floor(p.y()+.9);y++)for(int z=(int)Math.floor(p.z()-.3);z<=Math.floor(p.z()+.3);z++)
            if(w.get(GroundSpace.TOPOLOGY.canonical(new Cell(pose.face(),x,y,z)).cell())!=0)return false;
        return true;
    }
    private static Vector3d vec(Point p){return new Vector3d(p.x(),p.y(),p.z());}
    private GroundFlight(){}
}

package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import org.joml.Quaterniond;

/** Unit AABB walking and flight. Root changes transport pose AND orientation, never deform blocks. */
public final class GroundMotion {
    public record State(GroundSpace.Pose pose,double vertical,boolean grounded,boolean flying,boolean jumpHeld,boolean cut,double qx,double qy,double qz,double qw){
        public State{double n=qx*qx+qy*qy+qz*qz+qw*qw;if(pose==null||!Double.isFinite(vertical)||Math.abs(vertical)>3||!Double.isFinite(n)||Math.abs(n-1)>.001)throw new IllegalArgumentException("Body");}
        public State(GroundSpace.Pose p,double v,boolean grounded,boolean flying,boolean jump,boolean cut,Quaterniond q){this(p,v,grounded,flying,jump,cut,q.x,q.y,q.z,q.w);}
        public Quaterniond orientation(){return new Quaterniond(qx,qy,qz,qw);}
    }
    public static State spawn(GroundWorld w,GroundSpace.Pose pose,double yaw){if(!clear(w,pose))throw new IllegalStateException("Spawn occupied; no blocks removed");return new State(pose,0,false,false,false,false,new Quaterniond().rotationY(yaw));}
    public static State step(GroundWorld w,State old,PlanetMotion.Input in,boolean toggle){
        boolean flying=toggle?!old.flying:old.flying,jump=in.rise()>0;double vy=toggle?0:old.vertical;var p=old.pose.point();var chart=new GroundChart(old.pose.face());var q=GroundView.upright(in.orientation());
        var up=new Point(0,1,0);var f=PlanetMotion.direction(q,0,0,1);var l=PlanetMotion.direction(q,1,0,0);var horizontal=new Point(f.x(),0,f.z());if(horizontal.length()<1e-5)horizontal=l.cross(up);horizontal=PlanetSpace.unit(horizontal);var d=horizontal.scale(in.forward()).add(up.cross(horizontal).scale(in.left()));if(d.length()>1)d=PlanetSpace.unit(d);
        if(flying){vy=0;d=(in.direct()?f.scale(in.forward()).add(l.scale(in.left())):d).add(up.scale(in.rise()));d=d.scale((in.fast()?1.2:.35)/Math.max(1,d.length()));}
        else{if(old.grounded&&jump&&!old.jumpHeld)vy=.42;else vy=Math.max(-3,vy-.08);d=d.scale(in.fast()?.30:.215).add(up.scale(vy));}
        d=new Point(d.x(),Math.clamp(p.y()+d.y(),GroundSpace.MIN+1,GroundSpace.CEILING)-p.y(),d.z());
        var end=ChartLabMotion.sweep(p,d,(x,y,z)->w.material(chart,x,y,z)!=0);
        // No fabricated invisible wall. Explicitly refuse a step into an unavailable net quadrant.
        if(!chart.bodyFits(end))return new State(old.pose,0,old.grounded,flying,jump,true,q);
        boolean grounded=false;if(!flying){var probe=ChartLabMotion.sweep(end,new Point(0,-.06,0),(x,y,z)->w.material(chart,x,y,z)!=0);grounded=end.y()-probe.y()<.045;if(grounded&&vy<0||vy>0&&end.y()-p.y()<vy*.25)vy=0;}
        var r=GroundSpace.canonical(old.pose.face(),end);q.premul(new Quaterniond().rotationY(-r.turns()*Math.PI/2)).normalize();
        return new State(r.pose(),vy,grounded,flying,jump,false,q);
    }
    public static boolean clear(GroundWorld w,GroundSpace.Pose pose){var chart=new GroundChart(pose.face());var p=pose.point();if(!chart.bodyFits(p))return false;for(int x=(int)Math.floor(p.x()-.3);x<=Math.floor(p.x()+.3);x++)for(int y=(int)Math.floor(p.y()-.9);y<=Math.floor(p.y()+.9);y++)for(int z=(int)Math.floor(p.z()-.3);z<=Math.floor(p.z()+.3);z++)if(w.material(chart,x,y,z)!=0)return false;return true;}
    public static boolean intersects(GroundSpace.Pose pose,CubeSurfaceTopology.Cell cell){var t=new GroundChart(pose.face()).tile(cell.face());if(t==null)return false;var d=t.point(new Point(cell.u()+.5,cell.h()+.5,cell.v()+.5)).sub(pose.point());return Math.abs(d.x())<.802&&Math.abs(d.y())<1.402&&Math.abs(d.z())<.802;}
    private GroundMotion(){}
}

